//! UI DTOs: the only shapes the webview sees. TypeScript copies are
//! generated by ts-rs (`cargo test` writes `src/lib/bindings`).

use ipc_contracts::proto::{self, HumanContinuationDecision, WidgetDraftState, WidgetDraftStatus};
use serde::Serialize;
use ts_rs::TS;

#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, TS)]
#[serde(rename_all = "camelCase")]
#[ts(export)]
pub enum ConnectionState {
    Connected,
    Unavailable,
    Incompatible,
    Security,
    Error,
}

#[derive(Debug, Clone, Serialize, TS)]
#[serde(rename_all = "camelCase")]
#[ts(export)]
pub struct ConnectionDto {
    pub state: ConnectionState,
    pub protocol: Option<u32>,
    pub daemon_build: Option<String>,
    pub client_build: String,
    pub detail: Option<String>,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, TS)]
#[serde(rename_all = "camelCase")]
#[ts(export)]
pub enum UiErrorKind {
    Unavailable,
    Incompatible,
    Security,
    Invalid,
    Business,
    Ambiguous,
    Internal,
}

#[derive(Debug, Clone, Serialize, TS)]
#[serde(rename_all = "camelCase")]
#[ts(export)]
pub struct UiError {
    pub kind: UiErrorKind,
    pub message: String,
}

impl UiError {
    pub fn new(kind: UiErrorKind, message: impl Into<String>) -> Self {
        Self {
            kind,
            message: message.into(),
        }
    }
}

#[derive(Debug, Clone, Serialize, TS)]
#[serde(rename_all = "camelCase")]
#[ts(export)]
pub struct ProjectDto {
    pub id: String,
    pub name: String,
}

impl From<proto::ProjectDto> for ProjectDto {
    fn from(value: proto::ProjectDto) -> Self {
        Self {
            id: value.id,
            name: value.name,
        }
    }
}

#[derive(Debug, Clone, Serialize, TS)]
#[serde(rename_all = "camelCase")]
#[ts(export)]
pub struct TaskDto {
    pub id: String,
    pub project_id: String,
    pub objective: String,
    /// Canonical lifecycle name exactly as agentd reports it (DRAFT, READY, ...).
    pub state: String,
    /// Direct dependency ids, in id order.
    pub depends_on: Vec<String>,
}

impl From<proto::TaskDto> for TaskDto {
    fn from(value: proto::TaskDto) -> Self {
        Self {
            id: value.id,
            project_id: value.project_id,
            objective: value.objective,
            state: value.state,
            depends_on: value.depends_on,
        }
    }
}

#[derive(Debug, Clone, Serialize, TS)]
#[serde(rename_all = "camelCase")]
#[ts(export)]
pub struct DecisionDto {
    pub request_id: String,
    pub task_id: String,
    pub reason: String,
    pub risk: String,
    pub affected_scope: Vec<String>,
    pub options: Vec<String>,
    pub recommendation: Option<String>,
    pub evidence: Vec<String>,
    pub status: String,
    #[ts(type = "number")]
    pub created_at_ms: u64,
    #[ts(type = "number | null")]
    pub expires_at_ms: Option<u64>,
}

/// Wire enum value to its canonical name; unknown values stay visible
/// instead of being dropped.
fn decision_name(value: i32) -> String {
    HumanContinuationDecision::try_from(value)
        .map(|decision| decision.as_str_name().to_owned())
        .unwrap_or_else(|_| format!("UNKNOWN_{value}"))
}

impl From<proto::HumanDecisionDto> for DecisionDto {
    fn from(value: proto::HumanDecisionDto) -> Self {
        Self {
            request_id: value.request_id,
            task_id: value.task_id,
            reason: value.reason,
            risk: value.risk,
            affected_scope: value.affected_scope,
            options: value.options.into_iter().map(decision_name).collect(),
            recommendation: value.recommendation.map(decision_name),
            evidence: value.evidence,
            status: value.status,
            created_at_ms: value.created_at_ms,
            expires_at_ms: value.expires_at_ms,
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn decision_options_keep_canonical_names_and_surface_unknown_values() {
        let wire = proto::HumanDecisionDto {
            request_id: "hd-1".to_owned(),
            options: vec![
                HumanContinuationDecision::Resume as i32,
                HumanContinuationDecision::Takeover as i32,
                99,
            ],
            recommendation: Some(HumanContinuationDecision::Replan as i32),
            created_at_ms: 1_793_000_000_000,
            ..Default::default()
        };
        let dto = DecisionDto::from(wire);
        assert_eq!(dto.options, ["RESUME", "TAKEOVER", "UNKNOWN_99"]);
        assert_eq!(dto.recommendation.as_deref(), Some("REPLAN"));
        assert_eq!(dto.created_at_ms, 1_793_000_000_000);
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, TS)]
#[serde(rename_all = "camelCase")]
#[ts(export)]
pub enum WidgetDraftStateDto {
    Running,
    Proposed,
    Refused,
    Failed,
    Cancelled,
}

#[derive(Debug, Clone, Serialize, TS)]
#[serde(rename_all = "camelCase")]
#[ts(export)]
pub struct WidgetDraftDto {
    pub job_id: String,
    pub state: WidgetDraftStateDto,
    pub source: Option<widget_spec::SourceType>,
    pub repo: Option<widget_spec::RepoName>,
    pub failure_code: Option<String>,
    pub failure_detail: Option<String>,
}

impl TryFrom<WidgetDraftStatus> for WidgetDraftDto {
    type Error = UiError;

    /// agentd already validated these; the host checks again at its own boundary.
    fn try_from(status: WidgetDraftStatus) -> Result<Self, UiError> {
        let invalid = |detail: String| UiError::new(UiErrorKind::Internal, detail);
        let state = match WidgetDraftState::try_from(status.state) {
            Ok(WidgetDraftState::WidgetDraftRunning) => WidgetDraftStateDto::Running,
            Ok(WidgetDraftState::WidgetDraftProposed) => WidgetDraftStateDto::Proposed,
            Ok(WidgetDraftState::WidgetDraftRefused) => WidgetDraftStateDto::Refused,
            Ok(WidgetDraftState::WidgetDraftFailed) => WidgetDraftStateDto::Failed,
            Ok(WidgetDraftState::WidgetDraftCancelled) => WidgetDraftStateDto::Cancelled,
            _ => return Err(invalid(format!("unknown draft state {}", status.state))),
        };
        let proposed = state == WidgetDraftStateDto::Proposed;
        let source = if proposed {
            Some(
                widget_spec::SourceType::from_wire(&status.source_type)
                    .map_err(|error| invalid(error.to_string()))?,
            )
        } else {
            None
        };
        let repo = if proposed && !status.repo.is_empty() {
            Some(widget_spec::RepoName::try_from(status.repo).map_err(invalid)?)
        } else {
            None
        };
        let failed = state == WidgetDraftStateDto::Failed;
        Ok(Self {
            job_id: status.job_id,
            state,
            source,
            repo,
            failure_code: failed.then_some(status.failure_code),
            failure_detail: failed.then_some(status.failure_detail),
        })
    }
}

#[cfg(test)]
mod widget_tests {
    use super::*;
    use ts_rs::TS;

    /// The layout types live in `widget-spec`; their TypeScript copies are
    /// written here, with the other bindings.
    #[test]
    fn export_widget_spec_bindings() {
        widget_spec::DashboardLayout::export_all(&ts_rs::Config::from_env())
            .expect("export layout bindings");
    }

    fn status(state: WidgetDraftState, source: &str, repo: &str) -> WidgetDraftStatus {
        WidgetDraftStatus {
            job_id: "draft-1".to_owned(),
            state: state as i32,
            source_type: source.to_owned(),
            repo: repo.to_owned(),
            failure_code: String::new(),
            failure_detail: String::new(),
        }
    }

    #[test]
    fn the_host_rechecks_a_proposal_from_agentd() {
        let good = status(
            WidgetDraftState::WidgetDraftProposed,
            "github.repo.stars",
            "cli/cli",
        );
        assert!(WidgetDraftDto::try_from(good).is_ok());
        let no_repo = status(
            WidgetDraftState::WidgetDraftProposed,
            "github.repo.stars",
            "",
        );
        assert!(WidgetDraftDto::try_from(no_repo)
            .expect("valid")
            .repo
            .is_none());
        for (source, repo) in [
            ("http://example.com", "cli/cli"),
            ("github.repo.stars", "http://example.com"),
            ("github.repo.stars", "cli/cli/../x"),
        ] {
            let bad = status(WidgetDraftState::WidgetDraftProposed, source, repo);
            assert!(WidgetDraftDto::try_from(bad).is_err(), "{source} {repo}");
        }
    }
}
